(require (quote [glitter.core :as c]) (quote [glitter.test-renderer :as tr]))
(defn require! [ok message] (when-not ok (throw (ex-info message {}))))
(let [r (tr/renderer) root (atom {:tag-name "body" :children []})
      view (fn [ks] (into [:ul] (map (fn [k] [:li {:glitter/key k} (str k)]) ks)))
      before (c/reconcile r root (view [0 1 2]))
      old-nodes (:children @(first (:children @root)))
      _ (tr/reset-events! r)
      after (c/reconcile r root (view [1 2 0]) (:vdom before) before)
      children (:children @(first (:children @root)))
      actual (mapv #(-> % deref :children first deref :text) children)]
 (prn :defect :append-move :expected ["1" "2" "0"] :actual actual :events (tr/events r))
 (require! (= ["0" "1" "2" "0"] actual) "Known append-move defect changed")
 (require! (identical? (first children) (last children)) "Duplicate entries must be the same live node")
 (require! (= [[:append-child "li" :to "ul"]] (tr/events r)) "Unexpected mutation path"))
(let [r (tr/renderer) root (atom {:tag-name "body" :children []}) calls (atom [])
      record (fn [e] (swap! calls conj (:glitter/life-cycle e)))
      before (c/reconcile r root [:ul [:li {:glitter/on-mount record :glitter/on-unmount record} "leaf"]])
      after (c/reconcile r root nil (:vdom before) before)]
 (prn :defect :descendant-unmount :expected [:glitter.life-cycle/mount :glitter.life-cycle/unmount] :actual @calls)
 (require! (= [:glitter.life-cycle/mount] @calls) "Known descendant-unmount defect changed")
 (require! (empty? (:children @root)) "Removal must have occurred"))
(println "Target-only known-defect assertions passed; Hegel not loaded.")
